css:
.diferencial-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 20px; }
.diferencial-card {
  background: var(--bg-alt); border: 1px solid var(--border); border-radius: 16px; padding: 36px 32px;
  display: flex; flex-direction: column; gap: 24px; min-height: 300px; transition: border-color 0.3s;
}
.diferencial-card:hover { border-color: var(--border-alt); }
.diferencial-card .top-row { display: flex; justify-content: space-between; align-items: flex-start; }
.diferencial-icon {
  width: 48px; height: 48px; border-radius: 10px; background: rgba(14,165,233,0.08); color: var(--accent);
  display: flex; align-items: center; justify-content: center;
}
.diferencial-num { font-family: 'JetBrains Mono', monospace; font-size: 10px; color: var(--text-faint); letter-spacing: 0.15em; }
.diferencial-card .body { flex: 1; }
.diferencial-card .title { font-family: 'Sora', sans-serif; font-weight: 700; font-size: 24px; letter-spacing: -0.02em; margin-bottom: 14px; }
.diferencial-card .desc { font-family: 'Manrope', sans-serif; font-size: 15px; color: var(--text-muted); line-height: 1.6; }
.diferencial-bar { height: 2px; width: 32px; background: var(--accent); }
